INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Decentralised Peppol (EHF 3.0)', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. Skattedirektoratet''s remaining technical regulations (due by 15 December 2026) will refine invoice format detail, exemptions, and digital bookkeeping criteria — confirm current requirements directly with Skatteetaten before building an integration.', 'Norway''s mandate is now genuinely enacted law, not a proposal — and it''s deliberately asymmetric: issuing arrives three years before receiving does.', 'EHF is Norway''s own name for what is, underneath, a Peppol BIS Billing 3.0 document — there''s no separate national schema to learn.', 'Norway''s mandate is deliberately asymmetric for three years — a design choice, not an oversight, aimed at giving buyers time to catch up.', 'Norway''s existing voluntary adoption is already high (84–89%), so for many businesses this is a matter of formalising practice already in place.', 'No clearance model or real-time reporting exists yet — but the infrastructure being built quietly creates the preconditions for one.' FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'EHF 3.0', 'National invoice format');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '~360k', 'Registered ELMA receivers');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '84–89%', 'Existing voluntary adoption');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '3 yrs', 'Gap between issue & receive mandates');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'Jun 2026', 'Law formally enacted');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format', '[["Domestic format", "EHF 3.0 (Elektronisk Handelsformat)"], ["Underlying standard", "Peppol BIS Billing 3.0 / UBL, EN 16931"], ["Cross-border", "Peppol BIS accepted directly"]]', 'EHF is typically used for domestic transactions while Peppol BIS handles both domestic and cross-border — for compliance purposes, both satisfy the legal requirement equally.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers', '[["Participant scheme", "0192 (ICD code for Norwegian organisasjonsnummer)"], ["Common shorthand", "\"0192\" and \"NO ORGNR\" in vendor documentation"]]', 'Routing identity ties directly to the organisation number — get this field wrong and delivery simply fails, regardless of how correct the rest of the invoice is.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Foreign entities', '[["Scope", "Same EHF requirements as Norwegian companies"], ["Trigger", "Local bookkeeping obligations under the Norwegian Bookkeeping Act"]]', 'If a foreign entity holds Norwegian bookkeeping obligations, there''s no lighter-touch version of the mandate — the exact same EHF rules apply when invoicing domestic business partners.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Exemptions', '[["Small sole proprietorships", "Turnover below NOK 50,000, if not VAT-registered"], ["B2C", "Explicitly excluded from the mandate"]]', 'A future B2C e-receipts framework is being separately assessed by Skattedirektoratet — worth watching, but not part of the current B2B reform.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Network model', '[["Model", "Peppol four-corner (decentralised)"], ["Routing", "Any Access Point can route to any other"], ["Clearance authority", "None"]]', 'There''s no requirement for point-to-point connections between trading partners — this is the same architecture powering Belgium''s and the UK''s B2B mandates.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'ELMA registry', '[["Full name", "Elektronisk Mottakeradresseregister"], ["Operator", "DFØ (Norwegian Agency for Public and Financial Management)"], ["Role", "National Service Metadata Publisher (SMP), integrated into the Peppol directory"]]', 'Senders must automatically query ELMA to verify a buyer''s e-delivery address and capability before transmitting — this lookup is what determines whether the 2027 issuing obligation even applies to a given recipient.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'The 2027–2030 asymmetry', '[["From 2027", "Vendors must issue to ELMA-registered buyers"], ["Until 2030", "Buyers not obliged to be able to receive"]]', 'This creates a genuine three-year gap where the sending obligation runs ahead of any universal receiving requirement — deliberately designed to give SMEs a longer runway to adapt.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 3 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Self-billing', '[["Permitted", "Yes"], ["Structured EHF required", "From 1 Jan 2027, where both parties are bookkeeping-liable and the buyer is in ELMA"]]', 'If you already self-bill, don''t assume that arrangement is grandfathered out of the structured-format requirement once 2027 arrives.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📊 Post-audit today, groundwork for more tomorrow', NULL, NULL, 'Norway currently operates a post-audit model with no real-time reporting. But the combination of mandatory structured invoicing, digital bookkeeping, and Peppol creates the technical preconditions for a future shift toward periodic or real-time reporting — without necessarily requiring a full clearance architecture like Italy''s or Poland''s.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🇩🇰 A deliberate nod to Denmark', NULL, NULL, 'The investigation behind this mandate explicitly considered a Danish-style mandatory digital bookkeeping requirement — Norway''s reform is consciously modelled on, though not identical to, its neighbour''s approach.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📈 High existing adoption softens the shock', NULL, NULL, 'With voluntary EHF/Peppol adoption already estimated at 84–89%, the 2027 mandate largely formalises current practice for companies already sending and receiving structured invoices — the compliance gap is real, but narrower than the headline dates suggest.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 3 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🧾 SAF-T stays relevant', NULL, NULL, 'Norway''s existing SAF-T reporting infrastructure sits alongside this reform — expect the two to increasingly reference each other as the 2030 digital bookkeeping requirement takes shape.', NULL, NULL);
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Register your company in ELMA', 'Confirm your organisation is listed and discoverable in the national receiver register, now integrated into the Peppol directory — this is a prerequisite for both sending and receiving.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Select a certified Peppol Access Point provider', 'Choose a provider well before Q3 2026 to allow time for integration and testing ahead of the January 2027 deadline.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your ERP can emit EHF 3.0', 'Validate that outgoing invoices are correctly structured Peppol BIS Billing 3.0 XML — this is the same underlying format regardless of whether you call it "EHF" or "Peppol BIS" internally.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Build the ELMA lookup into your invoicing workflow', 'Query ELMA automatically before transmission to check whether a given recipient is registered and what capability they''ve declared — this determines whether the structured-format obligation applies to that specific invoice.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Foreign entities: confirm your Norwegian bookkeeping obligation status', 'If you have a local presence that triggers Norwegian bookkeeping rules, plan for identical EHF compliance — there''s no separate lighter regime for non-Norwegian companies.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Start planning your 2030 digital bookkeeping upgrade now', 'Even though reception isn''t mandatory until 2030, the three-year runway is there to be used — don''t leave the automatic-receiving-and-processing requirement until the last minute.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 6 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Use the free support available', 'Skatteetaten and Digdir offer guidance, SAF-T documentation, and Peppol information, including free webinars — genuinely worth using given the technical detail still being finalised through late 2026.');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.skatteetaten.no', 0 FROM countries WHERE name_en = 'Norway';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'Skatteetaten (Norwegian Tax Administration)');
